with city_rows(name,slug) as (values ('Aachen','aachen'),('Bonn','bonn'),('Berlin','berlin'),('Dresden','dresden'),('Hamburg','hamburg'),('Heidelberg','heidelberg'),('Karlsruhe','karlsruhe'),('Munich','munich'),('Tübingen','tuebingen')) insert into core.geographies(id,country_code,geography_type,name,slug,metadata,status) select md5('de:city:'||slug)::uuid,'DE','city',name,slug,jsonb_build_object('source_tier','official_federal_research_strategy','source_system','DFG_EXCELLENCE_STRATEGY','normalization_batch','de_excellence_locations_v1'),'active' from city_rows on conflict(id) do update set name=excluded.name,slug=excluded.slug,metadata=coalesce(core.geographies.metadata,'{}'::jsonb)||excluded.metadata,status=excluded.status,updated_at=now(); with location_rows(domain_key,city_name,city_slug) as (values ('rwth-aachen.de','Aachen','aachen'),('uni-bonn.de','Bonn','bonn'),('fu-berlin.de','Berlin','berlin'),('hu-berlin.de','Berlin','berlin'),('tu.berlin','Berlin','berlin'),('tu-dresden.de','Dresden','dresden'),('uni-hamburg.de','Hamburg','hamburg'),('uni-heidelberg.de','Heidelberg','heidelberg'),('kit.edu','Karlsruhe','karlsruhe'),('lmu.de','Munich','munich'),('tum.de','Munich','munich'),('uni-tuebingen.de','Tübingen','tuebingen')), resolved as (select identity.institution_id,identity.official_domain,identity.official_domain_source_url,l.city_name,l.city_slug,g.id geography_id from location_rows l join public.institution_identity_de_v1 identity on identity.official_domain=l.domain_key join core.geographies g on g.country_code='DE' and g.geography_type='city' and g.slug=l.city_slug and g.status='active') insert into catalog.campuses(id,institution_id,name,city,locality,country_code,geography_id,locality_geography_id,official_url,source_url,source_checked_at,metadata,status) select md5('de:excellence-city:'||official_domain)::uuid,institution_id,'Verified institution city',city_name,city_name,'DE',geography_id,geography_id,official_domain_source_url,'https://www.dfg.de/en/service/press/press-releases/2026/press-release-no-04',now(),jsonb_build_object('record_scope','tier_a_institution_city','location_quality','verified_official_city','display_policy','preferred','source_tier','official_federal_research_strategy','source_system','DFG_EXCELLENCE_STRATEGY','official_domain',official_domain,'location_key','dfg-excellence-site-city','coordinate_precision','not_asserted','campus_inventory_complete',false,'programme_assignment_verified',false,'normalization_batch','de_excellence_locations_v1'),'active' from resolved on conflict(id) do update set name=excluded.name,city=excluded.city,locality=excluded.locality,geography_id=excluded.geography_id,locality_geography_id=excluded.locality_geography_id,official_url=excluded.official_url,source_url=excluded.source_url,source_checked_at=excluded.source_checked_at,metadata=excluded.metadata,status=excluded.status,updated_at=now(); create or replace view public.institution_location_de_v1 with(security_invoker=true) as select c.institution_id,c.id campus_id,c.name,g.name city_name,g.slug city_slug,coalesce(nullif(c.city,''),nullif(c.locality,'')) reported_city,c.region,c.address_line,c.postal_code,c.official_url,c.source_url,c.source_checked_at,c.metadata->>'location_quality' location_quality,c.metadata->>'record_scope' record_scope,c.metadata->>'official_domain' official_domain from catalog.campuses c join catalog.institutions i on i.id=c.institution_id and i.country_code='DE' left join core.geographies g on g.id=coalesce(c.locality_geography_id,c.geography_id) and g.status='active' where c.status<>'inactive' and c.metadata->>'location_quality'='verified_official_city'; revoke all on public.institution_location_de_v1 from public,anon,authenticated; grant select on public.institution_location_de_v1 to service_role; do $$ declare c int; begin select count(*) into c from public.institution_location_de_v1; if c<>12 then raise exception 'Expected 12 DE locations, found %',c; end if; select count(*) into c from catalog.campuses cp join catalog.institutions i on i.id=cp.institution_id where i.country_code='DE' and cp.status<>'inactive' and cp.metadata->>'location_quality'='verified_official_city' and (cp.latitude is not null or cp.longitude is not null or cp.address_line is not null or cp.postal_code is not null); if c>0 then raise exception 'DE locations assert unverified precision %',c; end if; end $$;;
